SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;
SET time_zone = '+07:00';

-- 1. BERSIHKAN TABEL TRANSAKSI LAMA (Gunakan DELETE FROM agar kompatibel dengan foreign key di InnoDB/phpMyAdmin)
DELETE FROM `payments`;
DELETE FROM `order_items`;
DELETE FROM `orders`;
DELETE FROM `invoices`;

ALTER TABLE `payments` AUTO_INCREMENT = 1;
ALTER TABLE `order_items` AUTO_INCREMENT = 1;
ALTER TABLE `orders` AUTO_INCREMENT = 1;
ALTER TABLE `invoices` AUTO_INCREMENT = 1;

-- 2. SEED INVOICES (12 Faktur Tempo, Piutang Berjalan & Pelunasan)

-- 3. SEED ORDERS (32 Pesanan: Menunggu Verifikasi, Pembayaran, Siap Kirim, Dalam Pengiriman, Selesai, Selesai Catatan & Batal)

-- 4. SEED ORDER ITEMS (110 Rincian Komoditas Selada, Brokoli, Tomat, Stroberi, Kol, Wortel)

